"use strict";

const http = require("http");
const https = require("https");
const zlib = require("zlib");
const { URL } = require("url");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

const NAV_HEADERS = {
  "user-agent": UA,
  accept:
    "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
  "accept-language": "ko-KR,ko;q=0.9,en-US;q=0.8,en;q=0.7",
  "accept-encoding": "gzip, deflate, br",
  "sec-ch-ua": '"Chromium";v="126", "Google Chrome";v="126", "Not;A=Brand";v="24"',
  "sec-ch-ua-mobile": "?0",
  "sec-ch-ua-platform": '"Windows"',
  "sec-fetch-dest": "document",
  "sec-fetch-mode": "navigate",
  "sec-fetch-site": "none",
  "upgrade-insecure-requests": "1",
};

const cleanUrl = (u) =>
  u ? u.replace(/\\u002F/g, "/").replace(/\\/g, "").replace(/&amp;/g, "&") : null;

const decodeHtmlEntities = (s) =>
  s
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(parseInt(n, 10)))
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&");

class Jar {
  constructor() {
    this.map = new Map();
  }
  absorb(setCookie) {
    const lines = Array.isArray(setCookie) ? setCookie : setCookie ? [setCookie] : [];
    for (const line of lines) {
      const pair = String(line).split(";")[0];
      const i = pair.indexOf("=");
      if (i > 0) this.map.set(pair.slice(0, i).trim(), pair.slice(i + 1).trim());
    }
  }
  toString() {
    return [...this.map.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
  }
}

function fetchTextOnce(urlStr, jar, headers, timeoutMs) {
  return new Promise((resolve, reject) => {
    let target;
    try {
      target = new URL(urlStr);
    } catch {
      reject(new Error(`Invalid URL: ${urlStr}`));
      return;
    }
    const lib = target.protocol === "http:" ? http : https;
    const req = lib.request(
      target,
      {
        method: "GET",
        headers: { ...NAV_HEADERS, cookie: jar.toString(), ...(headers || {}) },
      },
      (res) => {
        jar.absorb(res.headers["set-cookie"]);
        let stream = res;
        const enc = String(res.headers["content-encoding"] || "").toLowerCase();
        if (enc === "gzip") stream = res.pipe(zlib.createGunzip());
        else if (enc === "deflate") stream = res.pipe(zlib.createInflate());
        else if (enc === "br") stream = res.pipe(zlib.createBrotliDecompress());
        const chunks = [];
        stream.on("data", (c) => chunks.push(c));
        stream.on("end", () =>
          resolve({
            status: res.statusCode || 0,
            headers: res.headers,
            text: Buffer.concat(chunks).toString("utf8"),
          })
        );
        stream.on("error", reject);
        res.on("error", reject);
      }
    );
    req.setTimeout(timeoutMs, () =>
      req.destroy(new Error(`Request timed out after ${timeoutMs}ms: ${urlStr}`))
    );
    req.on("error", reject);
    req.end();
  });
}

async function fetchText(url, jar, headers, timeoutMs = 25000, redirects = 5) {
  let lastErr = null;
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const res = await fetchTextOnce(url, jar, headers, timeoutMs);
      if (
        res.status >= 300 &&
        res.status < 400 &&
        res.headers.location &&
        redirects > 0
      ) {
        const next = new URL(res.headers.location, url).toString();
        return fetchText(next, jar, headers, timeoutMs, redirects - 1);
      }
      return { ...res, url };
    } catch (e) {
      lastErr = e;
      await new Promise((r) => setTimeout(r, 700));
    }
  }
  throw lastErr || new Error(`Request failed: ${url}`);
}

function parseJsonObjectAt(text, start) {
  let depth = 0;
  let inStr = false;
  let esc = false;
  for (let i = start; i < text.length; i++) {
    const c = text[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === "\\") esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') inStr = true;
    else if (c === "{") depth++;
    else if (c === "}") {
      depth--;
      if (depth === 0) {
        try {
          return JSON.parse(text.slice(start, i + 1));
        } catch {
          return null;
        }
      }
    }
  }
  return null;
}

function extractEmbeddedState(html) {
  const nextData = html.match(
    /<script[^>]+id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/
  );
  if (nextData) {
    try {
      const parsed = JSON.parse(nextData[1]);
      if (parsed) return parsed;
    } catch {

    }
  }
  for (const marker of ["__PRELOADED_STATE__", "__INITIAL_STATE__", "__APP_STATE__"]) {
    const at = html.indexOf(marker);
    if (at < 0) continue;
    const open = html.indexOf("{", at);
    if (open < 0) continue;
    const parsed = parseJsonObjectAt(html, open);
    if (parsed) return parsed;
  }
  return null;
}

function walkObjects(root, visit, depth = 0) {
  if (!root || typeof root !== "object" || depth > 14) return;
  visit(root);
  if (Array.isArray(root)) {
    for (const item of root) walkObjects(item, visit, depth + 1);
  } else {
    for (const value of Object.values(root)) walkObjects(value, visit, depth + 1);
  }
}

function findPlayInfo(root) {
  let found = null;
  walkObjects(root, (obj) => {
    if (found) return;
    const lists = [obj.videos, obj.streams];
    for (const list of lists) {
      if (!Array.isArray(list)) continue;
      const usable = list.filter(
        (v) => v && typeof v.source === "string" && /^https?:\/\//.test(v.source)
      );
      if (usable.length) {
        found = { videos: usable, holder: obj };
        return;
      }
    }
  });
  return found;
}

function findPlaybackKey(root) {
  let key = null;
  walkObjects(root, (obj) => {
    if (key) return;
    for (const name of ["playbackKey", "playKey", "inKey", "key"]) {
      if (typeof obj[name] === "string" && obj[name].length >= 8) {
        key = obj[name];
        return;
      }
    }
  });
  return key;
}

function ogContent(html, property) {
  const m = html.match(
    new RegExp(`<meta[^>]+property="og:${property}"[^>]+content="([^"]*)"`)
  );
  return m ? decodeHtmlEntities(m[1]) : null;
}

function parseVideoId(input) {
  const s = String(input || "").trim();
  const m = s.match(/tv\.naver\.com\/(?:v|video)\/(\d+)/i);
  if (m) return m[1];
  if (/^\d{5,}$/.test(s)) return s;
  return null;
}

function shapeFromPlayInfo(play, html, fallbackTitle) {
  const videos = play.videos
    .map((v) => {
      const opt = v.encodingOption || {};
      const height =
        typeof opt.height === "number"
          ? opt.height
          : parseInt(String(opt.name || "").match(/(\d{3,4})/)?.[1] || "", 10) || null;
      return {
        quality: opt.name || (height ? `${height}p` : "source"),
        height,
        url: cleanUrl(v.source),
      };
    })
    .filter((v) => v.url)
    .sort((a, b) => (b.height || 0) - (a.height || 0));
  if (!videos.length) return null;
  const best = videos[0];
  const isHls = /\.m3u8($|\?)/i.test(best.url);
  const holder = play.holder || {};
  const download = {
    video: best.url,
    url: best.url,
    type: isHls ? "hls" : "mp4",
    note: "Signed URL — download immediately, it expires soon",
  };
  if (videos.length > 1) {
    download.qualities = videos.map((v) => ({ quality: v.quality, url: v.url }));
  }
  return {
    success: true,
    source: "Naver TV",
    data: {
      title:
        holder.title ||
        holder.subject ||
        ogContent(html, "title") ||
        fallbackTitle ||
        "Naver TV Video",
      author:
        (holder.channel && (holder.channel.name || holder.channel.title)) ||
        holder.channelName ||
        null,
      duration:
        typeof holder.duration === "number"
          ? holder.duration
          : typeof holder.playTime === "number"
            ? holder.playTime
            : null,
      thumbnail:
        cleanUrl(
          holder.thumbnailUrl ||
            holder.coverImageUrl ||
            ogContent(html, "image") ||
            null
        ) || null,
      download,
    },
  };
}

async function fetchSelf(url) {
  try {
    const id = parseVideoId(url);
    if (!id) throw new Error("Invalid Naver TV URL");

    const jar = new Jar();
    const pageUrl = `https://tv.naver.com/v/${id}`;
    const page = await fetchText(pageUrl, jar, { referer: "https://tv.naver.com/" });
    const html = page.text || "";

    if (
      (page.url && /:\/\/m\.naver\.com\/shorts/.test(page.url)) ||
      html.includes("TerminationNotice") ||
      html.includes("서비스 종료 안내") ||
      html.includes("서비스를 종료")
    ) {
      throw new Error(
        "Naver TV ended its service on 2026-09-30 — tv.naver.com now only serves a termination notice (pointing viewers to Naver Clip), so this video page no longer exists"
      );
    }
    if (page.status === 404) {
      throw new Error("Video not found — it may be deleted or private");
    }
    if (page.status !== 200) {
      throw new Error(`Naver TV returned HTTP ${page.status}`);
    }

    const state = extractEmbeddedState(html);
    if (state) {
      const play = findPlayInfo(state);
      if (play) {
        const shaped = shapeFromPlayInfo(play, html, null);
        if (shaped) return shaped;
      }
      const key = findPlaybackKey(state);
      if (key) {
        const api = await fetchText(
          `https://apis.naver.com/rmcnmv/rmcnmv/vod/play/v2.0/${id}?key=${encodeURIComponent(key)}`,
          jar,
          { referer: pageUrl, accept: "application/json, */*" }
        );
        if (api.status === 200) {
          try {
            const playJson = JSON.parse(api.text);
            const play = findPlayInfo(playJson);
            if (play) {
              const shaped = shapeFromPlayInfo(play, html, null);
              if (shaped) return shaped;
            }
          } catch {

          }
        }
      }
    }

    throw new Error(
      "Could not extract this video — no playable stream data was found on the page (it may require login, be region-locked, or Naver changed its page format)"
    );
  } catch (e) {
    if (/^Naver Error:/.test(e.message)) throw e;
    throw new Error("Naver Error: " + e.message);
  }
}

module.exports = fetchSelf;
